import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { FaCheckCircle, FaTimesCircle, FaExclamationCircle } from "react-icons/fa"; // Güncellenmiş simgeler

const AuthForm = () => {
  const [username, setUsername] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [passwordConf, setPasswordConf] = useState('');
  const [errors, setErrors] = useState({});
  const navigate = useNavigate();

  const validateForm = () => {
    let newErrors = {};
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    const usernameRegex = /^[a-zA-Z0-9_]+$/;
    const passwordRegex = /^(?=.*[A-Z])(?=.*\d)(?=.*[@$!%*?&.])[A-Za-z\d@$!%*?&.]{8,}$/;

    if (!username.trim()) newErrors.username = "Username is required";
    else if (!usernameRegex.test(username)) newErrors.username = "Username can only contain letters, numbers, and underscores";

    if (!email.trim()) newErrors.email = "Email is required";
    else if (!emailRegex.test(email)) newErrors.email = "Invalid email format";

    if (!password) newErrors.password = "Password is required";
    else if (!passwordRegex.test(password))
      newErrors.password = "Password must be at least 8 characters, include an uppercase letter, a number, and a special character";

    if (!passwordConf) newErrors.passwordConf = "Please confirm your password";
    else if (passwordConf !== password) newErrors.passwordConf = "Passwords do not match";

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    if (validateForm()) {
      console.log({ username, email, password, passwordConf });
      navigate('/personality-test');
    }
  };

  const handleLogoClick = () => {
    navigate("/index");
  };

  const checkPasswordCriteria = (password) => {
    return {
      length: password.length >= 8,
      uppercase: /[A-Z]/.test(password),
      number: /[0-9]/.test(password),
      specialChar: /[@$!%*?&.]/.test(password)
    };
  };

  const passwordCriteria = checkPasswordCriteria(password);

  return (
    <div>
      <header>
        <div className="logo">
          <h1 className="logo-text" onClick={handleLogoClick} style={{ cursor: "pointer" }}>SoulM</h1>
        </div>
      </header>
      <div className="auth-content">
        <div className="auth-form-container">
          <form onSubmit={handleSubmit}>
            <h2 className="form-title">Register</h2>
            <div>
              <label>Username</label>
              <input
                type="text"
                name="username"
                className="text-input"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
              />
              {errors.username && (
                <p className="error">
                  <FaExclamationCircle className="error-icon" /> {errors.username}
                </p>
              )}
            </div>
            <div>
              <label>Email</label>
              <input
                type="email"
                name="email"
                className="text-input"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
              />
              {errors.email && (
                <p className="error">
                  <FaExclamationCircle className="error-icon" /> {errors.email}
                </p>
              )}
            </div>
            <div>
              <label>Password</label>
              <input
                type="password"
                name="password"
                className="text-input"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
              />
              <div className="password-requirements">
                <p>
                  {passwordCriteria.length ? <FaCheckCircle className="valid-icon" /> : <FaTimesCircle className="invalid-icon" />}
                  At least 8 characters
                </p>
                <p>
                  {passwordCriteria.uppercase ? <FaCheckCircle className="valid-icon" /> : <FaTimesCircle className="invalid-icon" />}
                  One uppercase letter
                </p>
                <p>
                  {passwordCriteria.number ? <FaCheckCircle className="valid-icon" /> : <FaTimesCircle className="invalid-icon" />}
                  One number
                </p>
                <p>
                  {passwordCriteria.specialChar ? <FaCheckCircle className="valid-icon" /> : <FaTimesCircle className="invalid-icon" />}
                  One special character (., @, #, !, etc.)
                </p>
              </div>
              {errors.password && (
                <p className="error">
                  <FaExclamationCircle className="error-icon" /> {errors.password}
                </p>
              )}
            </div>
            <div>
              <label>Password Confirmation</label>
              <input
                type="password"
                name="passwordConf"
                className="text-input"
                value={passwordConf}
                onChange={(e) => setPasswordConf(e.target.value)}
              />
              {errors.passwordConf && (
                <p className="error">
                  <FaExclamationCircle className="error-icon" /> {errors.passwordConf}
                </p>
              )}
            </div>
            <div>
              <button type="submit" className="btn btn-big">
                Register
              </button>
            </div>
            <p>
              Or <Link to="/login" className="register-link">Sign In</Link>
            </p>
          </form>
        </div>
      </div>
      <div className="footer-summary">
        &copy; SoulM.com | Designed by Group 19
      </div>
    </div>
  );
};

export default AuthForm;
